class Solution {
public:
    int minimumCoins(vector<int>& prices) {
        int n = prices.size();
        vector<int> dp(n + 2, 0);
        for (int i = n; i >= 1; i--) {
            int reach = min(n + 1, 2 * i + 1);
            int min_next = dp[i + 1];
            for (int j = i + 1; j <= reach; j++) {
                min_next = min(min_next, dp[j]);
            }
            dp[i] = prices[i - 1] + min_next;
        }
        return dp[1];
    }
};

class Solution {
    public int minimumCoins(int[] prices) {
        int n = prices.length;
        int[] dp = new int[n + 2];
        for (int i = n; i >= 1; i--) {
            int reach = Math.min(n + 1, 2 * i + 1);
            int minNext = dp[i + 1];
            for (int j = i + 1; j <= reach; j++) {
                minNext = Math.min(minNext, dp[j]);
            }
            dp[i] = prices[i - 1] + minNext;
        }
        return dp[1];
    }
}

