var minimumCoins = function(prices) {
    const n = prices.length;
    const dp = new Int32Array(n + 2);
    for (let i = n; i >= 1; i--) {
        const reach = Math.min(n + 1, 2 * i + 1);
        let minNext = dp[i + 1];
        for (let j = i + 1; j <= reach; j++) {
            if (dp[j] < minNext) minNext = dp[j];
        }
        dp[i] = prices[i - 1] + minNext;
    }
    return dp[1];
};
